(function(){'use strict';
/* Components Database generator — jahdb-components-generator-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed always makes the same record.
   src:"public" = Fact-checked public information */
function pad(n){var s=String(n);while(s.length<6)s='0'+s;return s;}
var PREFIX='JAH-CPT-';
var SRC='public';
var RECORD_KIND='components record';
var ANGLES=['overview','detailed','examples','faq','history','applications'];
var TOPICS=[{"brief":"Electronic components are the building blocks of circuits — resistors, capacitors, chips — each performing a defined electrical function.","examples":["A phone contains thousands of components: processors, memory, sensors, and power parts.","A simple LED circuit needs just four: battery, resistor, LED, and switch."],"history":["Discrete components dominated until the 1960s; integrated circuits then packed thousands into one package.","Surface-mount technology in the 1980s shrank components and enabled modern miniaturization."],"points":["Passive components (resistors, capacitors, inductors) don't amplify; active ones (transistors, ICs) do.","Every component has ratings: voltage, current, power, tolerance — exceeding them destroys parts.","Datasheets are the contract: pinouts, specs, and operating limits for every part.","Through-hole parts suit prototyping; surface-mount dominates production."],"qa":[["Active vs. passive?","Active components control current flow (transistors); passive ones just resist, store, or filter it."],["What is a datasheet?","The manufacturer's specification document — the authoritative reference for a part."],["Why do components fail?","Overvoltage, overcurrent, overheating, and age — always design within ratings with margin."]],"title":"What Are Electronic Components","uses":["Building circuits from phones to power plants.","Prototyping ideas on breadboards.","Repairing devices by replacing failed parts."]},{"brief":"Resistors oppose current flow — setting currents, dividing voltages, and protecting sensitive parts — the most common component of all.","demo":{"kind":"runnable-program","note":"Run with: node demo.js — decode resistor color bands to ohms.","program":"// Resistor color codes — run with: node demo.js\nvar colors = { black: 0, brown: 1, red: 2, orange: 3, yellow: 4, green: 5, blue: 6, violet: 7, gray: 8, white: 9 };\nfunction decode(bands) {\n  var v = colors[bands[0]] * 10 + colors[bands[1]];\n  return v * Math.pow(10, colors[bands[2]]);\n}\n[['brown', 'black', 'red'], ['yellow', 'violet', 'orange'], ['red', 'red', 'brown']].forEach(function(b) {\n  console.log(b.join('-'), '->', decode(b), 'ohms');\n});"},"examples":["A 220-ohm resistor limits current through an LED.","A voltage divider of two resistors scales 5V down for a sensor input."],"history":["Carbon-composition resistors date to early radio; metal-film types brought precision in the mid-20th century.","Color-band coding standardized value reading before tiny printed numbers were feasible."],"points":["Ohm's Law rules: V = I × R — current through a resistor is proportional to voltage across it.","Key specs: resistance (ohms), tolerance (%), power rating (watts), and temperature coefficient.","Series adds resistances; parallel reduces: 1/R = 1/R1 + 1/R2.","Power dissipation P = I²R: undersized resistors overheat and fail."],"qa":[["How do you read color bands?","First two bands are digits, third is the multiplier (power of ten), fourth is tolerance."],["What is tolerance?","How far the actual resistance may deviate — 5% (gold) is common, 1% for precision."],["Why do resistors get hot?","They convert electrical energy to heat — that's their job; size the wattage accordingly."]],"title":"Resistors","uses":["Limiting current to protect LEDs and inputs.","Dividing voltages for sensors and references.","Pulling signals to defined logic levels."]},{"brief":"Capacitors store charge in an electric field — smoothing power supplies, coupling signals, and timing circuits.","examples":["A power supply's big capacitors smooth rectified AC into steady DC.","A tiny capacitor across a chip's power pins filters high-frequency noise."],"history":["The Leyden jar (1745) was the first capacitor; electrolytics and ceramics made them practical for electronics.","Multilayer ceramics in the 1980s-90s shrank high capacitance into tiny packages."],"points":["Capacitance (farads) measures charge stored per volt; common units are microfarads and picofarads.","Types: ceramic (small, cheap), electrolytic (large, polarized), film (stable, precise).","Polarized capacitors (electrolytic, tantalum) explode if reversed — observe polarity!","Capacitors block DC and pass AC — the basis of filters and coupling."],"qa":[["What is ESR?","Equivalent Series Resistance — parasitic resistance causing heating; low ESR matters in power circuits."],["Why do capacitors fail?","Drying out (electrolytics), overvoltage, or reverse polarity — bulging tops are the telltale sign."],["How do they smooth power?","By charging during peaks and discharging during dips — a reservoir for current."]],"title":"Capacitors","uses":["Smoothing power-supply ripple.","Filtering noise in audio and radio circuits.","Timing oscillators and setting filter frequencies."]},{"brief":"Inductors store energy in a magnetic field — resisting current changes, filtering noise, and enabling transformers and radios.","examples":["A choke inductor blocks high-frequency noise from entering a power supply.","An LC circuit tunes a radio to one station's frequency."],"history":["Faraday's induction (1831) founded the science; inductors were essential to early radio.","Ferrite cores in the 20th century shrank inductors for modern power supplies."],"points":["Inductance (henries) measures opposition to current change — the dual of capacitance.","Inductors pass DC and block AC — opposite of capacitors — forming filters together.","Saturation: beyond a current limit, the core saturates and inductance collapses.","Switching power supplies use inductors to convert voltages efficiently."],"qa":[["What is inductive kickback?","The voltage spike when current through an inductor is interrupted — it can destroy transistors; diodes tame it."],["Inductor vs. capacitor?","Inductors resist current change and store magnetic energy; capacitors resist voltage change and store electric energy."],["What is a choke?","An inductor used to block (choke off) high frequencies while passing DC."]],"title":"Inductors","uses":["Filtering power supplies and signals.","Building transformers and wireless chargers.","Tuning radio circuits with capacitors."]},{"brief":"Diodes conduct current in one direction only — rectifying AC to DC, protecting circuits, and emitting light as LEDs.","examples":["A bridge rectifier's four diodes convert wall AC into DC for electronics.","A flyback diode across a relay coil absorbs the inductive spike."],"history":["Vacuum-tube diodes (1904) gave way to semiconductor diodes in the 1940s-50s.","The LED (1962) turned the humble diode into the world's light source."],"points":["Forward bias conducts (with ~0.7V drop for silicon); reverse bias blocks until breakdown.","Types: rectifier (power), Schottky (fast, low drop), Zener (voltage reference), LED (light).","Zener diodes regulate voltage by breaking down predictably in reverse.","Always respect current ratings — diodes fail short and take neighbors with them."],"qa":[["What is forward voltage?","The drop across a conducting diode — ~0.7V silicon, ~0.3V Schottky, ~2-3V LED."],["What is reverse breakdown?","The voltage where a diode conducts backward — destructive except in Zeners designed for it."],["How do LEDs make light?","Electrons recombining across the semiconductor junction release photons."]],"title":"Diodes","uses":["Rectifying AC to DC in power supplies.","Protecting circuits from reverse polarity and spikes.","Lighting the world as LEDs."]},{"brief":"Transistors are electrically controlled switches and amplifiers — the fundamental active component behind all digital electronics.","examples":["A MOSFET switches a motor on and off from a microcontroller pin.","Billions of transistors in a CPU perform every computation."],"history":["The transistor was invented at Bell Labs in 1947 (Bardeen, Brattain, Shockley).","It replaced vacuum tubes, then integrated circuits packed millions onto chips."],"points":["BJT vs. MOSFET: current-controlled vs. voltage-controlled — MOSFETs dominate digital logic.","As a switch: fully on or off. As an amplifier: proportional control in the linear region.","Key ratings: max voltage, max current, power dissipation, and switching speed.","Every logic gate — AND, OR, NOT — is built from transistors."],"qa":[["NPN vs. PNP?","BJT polarities: NPN switches the low side, PNP the high side — mirror images."],["What is a MOSFET gate?","The voltage-controlled terminal — essentially no current flows into it, making drive easy."],["Why did transistors win?","Small, reliable, cool, and cheap — everything tubes weren't."]],"title":"Transistors","uses":["Switching loads from tiny signals.","Amplifying audio and radio signals.","Building every digital chip ever made."]},{"brief":"Integrated circuits pack entire circuits — transistors by the billions — into single packages, from simple timers to processors.","examples":["The 555 timer IC has run blinking LEDs since 1972.","A microcontroller IC contains CPU, memory, and peripherals in one chip."],"history":["Kilby (1958) and Noyce (1959) invented the IC; Moore's Law drove decades of doubling.","The 4004 (1971) put a CPU on one chip — the microprocessor era began."],"points":["Scale: SSI to VLSI to today's billions of transistors per chip.","Analog ICs (op-amps, regulators) and digital ICs (logic, memory, processors).","Packages: DIP for prototyping, QFP/QFN/BGA for dense production.","Datasheets define everything: pins, timing, power, and absolute maximums."],"qa":[["What is Moore's Law?","The observation that transistor counts doubled roughly every two years — now slowing."],["Analog vs. digital ICs?","Analog handle continuous signals; digital handle ones and zeros."],["What is a microcontroller?","An IC with CPU, memory, and I/O peripherals — a computer on a chip."]],"title":"Integrated Circuits (ICs)","uses":["Running computers, phones, and embedded devices.","Simplifying designs: one chip replaces dozens of discretes.","Enabling the entire digital age."]},{"brief":"LEDs (light-emitting diodes) convert electricity directly to light — efficient, long-lived, and everywhere from indicators to streetlights.","demo":{"kind":"runnable-program","note":"Run with: node demo.js — compute the current-limiting resistor for an LED.","program":"// LED resistor calculator — run with: node demo.js\nfunction ledResistor(vSupply, vLed, current) {\n  return (vSupply - vLed) / current;\n}\nvar cases = [\n  { s: 5, led: 2.0, i: 0.020 },\n  { s: 9, led: 3.2, i: 0.015 },\n  { s: 3.3, led: 2.0, i: 0.010 }\n];\ncases.forEach(function(c) {\n  console.log(c.s + 'V supply, ' + c.led + 'V LED @ ' + (c.i * 1000) + 'mA -> ' + Math.round(ledResistor(c.s, c.led, c.i)) + ' ohms');\n});"},"examples":["A 5V circuit drives a red LED through a 150-ohm resistor.","Streetlights retrofitted with LED arrays cut energy use by half."],"history":["The first practical LED (1962, Holonyak) was red; blue LEDs (1990s, Nakamura) enabled white lighting.","The 2014 Nobel Prize recognized the blue LED's world-changing impact."],"points":["LEDs need current limiting: a series resistor or constant-current driver — never connect directly to voltage.","Forward voltage varies by color: ~2V red, ~3.2V blue/white.","Efficiency: 100+ lumens per watt versus ~15 for incandescent.","Dimming via PWM (pulse-width modulation) preserves color better than reducing current."],"qa":[["Why does an LED need a resistor?","LEDs have almost no resistance when on — without limiting, current runs away and destroys them."],["What is PWM dimming?","Switching the LED on/off thousands of times per second — brightness follows the duty cycle."],["How long do LEDs last?","Tens of thousands of hours — limited by the driver electronics as much as the diode."]],"title":"LEDs","uses":["Indicating status in every electronic device.","Lighting homes, streets, and screens efficiently.","Displaying information in signs and matrices."]},{"brief":"Sensors convert physical phenomena — light, temperature, motion, pressure — into electrical signals machines can read.","examples":["A thermistor reports temperature to a thermostat.","An accelerometer in a phone detects screen rotation."],"history":["Early sensors were electromechanical; MEMS (1980s-90s) shrank them onto chips.","The smartphone era made accelerometers, gyros, and magnetometers ubiquitous."],"points":["Transduction: the physical-to-electrical conversion at every sensor's heart.","Key specs: range, accuracy, resolution, response time, and interface (analog, I2C, SPI).","Conditioning: amplification, filtering, and calibration turn raw signals into data.","Smart sensors integrate processing — outputting engineering units, not raw voltages."],"qa":[["Analog vs. digital sensors?","Analog output varying voltage; digital output numbers over a bus — digital is easier to use."],["What is calibration?","Mapping sensor output to true physical values — without it, readings are just numbers."],["What is MEMS?","Micro-Electro-Mechanical Systems — microscopic machines (accelerometers, microphones) on chips."]],"title":"Sensors","uses":["Measuring the physical world for control systems.","Enabling phones, cars, and wearables to perceive.","Feeding IoT and automation with data."]},{"brief":"Relays are electrically operated switches — a small current controlling a large one, isolating control from power circuits.","examples":["A microcontroller's 5V signal switches 240V mains through a relay.","Automotive relays control headlights and starters from dashboard switches."],"history":["Relays date to 1830s telegraphy; they built the first computers before transistors.","Solid-state relays (1970s) replaced moving parts with semiconductors."],"points":["Electromagnetic relays: a coil pulls contacts closed — audible click included.","Isolation: control and load circuits are electrically separate — safety by design.","Ratings: coil voltage, contact current/voltage, AC vs. DC — all must be respected.","Solid-state relays switch silently and fast but drop voltage and cost more."],"qa":[["Why use a relay?","To control high power from low-power logic, with electrical isolation between them."],["What is contact bounce?","Mechanical contacts chatter on closing — debounce in software or hardware."],["Relay vs. transistor?","Relays isolate and handle AC/high power; transistors switch faster and silently for DC."]],"title":"Relays","uses":["Switching mains power from low-voltage logic.","Isolating noisy loads from sensitive electronics.","Controlling motors, heaters, and lights."]},{"brief":"Switches make or break electrical connections by hand or mechanism — from pushbuttons to toggles to DIP selectors.","examples":["A tactile button resets a microcontroller.","A toggle switch selects a device's operating mode."],"history":["Knife switches are 19th century; modern tactile and slide switches miniaturized control.","Membrane and capacitive touch replaced many mechanical switches in the 2000s."],"points":["Poles and throws: SPST (simple on/off) to DPDT (two circuits, two positions).","Momentary (pushbutton) vs. latching (toggle) — action determines use.","Ratings: voltage, current, AC/DC — a mains switch can't be a signal switch.","Debouncing: mechanical contacts bounce — handle in hardware or software."],"qa":[["What is SPDT?","Single Pole, Double Throw — one input switched between two outputs."],["Why debounce?","Because contacts physically bounce, registering multiple presses for one."],["What is a DIP switch?","Tiny manual switches for configuring hardware options on a board."]],"title":"Switches","uses":["User input: buttons, toggles, and selectors.","Mode selection in hardware.","Reset and configuration controls."]},{"brief":"Connectors join circuits together — board-to-board, wire-to-board, and device-to-world — the mechanical half of every electrical interface.","examples":["USB-C connectors carry power and data to phones.","Screw terminals connect mains wiring securely."],"history":["Standardized connectors (USB 1996) ended the era of proprietary ports.","High-density board connectors enabled modern miniaturization."],"points":["Key specs: pin count, pitch, current rating, mating cycles, and retention.","Choose by use: USB for data+power, barrel jacks for power, headers for prototyping.","Mating cycles matter: a daily-plugged connector needs thousands of cycles.","Strain relief and locking prevent the #1 field failure: intermittent connections."],"qa":[["What is pitch?","The spacing between pins — 2.54mm for classic headers, down to 0.4mm for dense parts."],["Why do connectors fail?","Corrosion, wear, and mechanical stress — gold plating and locking help."],["What is a mating cycle?","One plug/unplug — rated lifetimes range from dozens to tens of thousands."]],"title":"Connectors","uses":["Joining boards, wires, and devices.","Enabling modular, serviceable designs.","Standardizing power and data interfaces."]},{"brief":"Printed circuit boards are the fiberglass-and-copper skeletons of electronics — routing thousands of connections reliably.","examples":["A phone's mainboard packs 10+ layers of traces in millimeters.","A hobbyist mills a single-layer board for a simple project."],"history":["PCBs replaced point-to-point wiring in the 1950s; multilayer boards arrived in the 1960s.","Cheap fabrication in the 2000s-2010s democratized custom boards."],"points":["Layers: copper traces on FR-4 fiberglass, joined by vias — 2 layers for simple, 8+ for dense.","Traces have current limits by width; high-speed signals need controlled impedance.","Solder mask insulates; silkscreen labels — the colors of a finished board.","Design rules: clearances, annular rings, and thermal reliefs that fabs can actually build."],"qa":[["What is a via?","A plated hole connecting traces between layers."],["What is FR-4?","The fiberglass-epoxy laminate most PCBs are built on."],["How are PCBs made?","Copper etched into traces, layers laminated, holes drilled and plated, then masked and finished."]],"title":"Printed Circuit Boards (PCBs)","uses":["Interconnecting every electronic product.","Prototyping circuits cheaply and quickly.","Learning electronics hands-on."]},{"brief":"Transformers transfer AC power between circuits via magnetic coupling — stepping voltage up or down with isolation.","examples":["A phone charger's transformer steps 120V down to 5V safely.","Power-grid transformers move energy at hundreds of kilovolts."],"history":["Faraday and Henry's induction (1831); practical transformers in the 1880s enabled AC power grids.","Switch-mode supplies in the late 20th century shrank transformers with high frequencies."],"points":["Turns ratio sets voltage ratio: 10:1 turns gives 10:1 voltage step-down.","Isolation: primary and secondary share no electrical connection — safety by physics.","Only AC transforms — DC needs switching to become pulsed AC first.","Losses: core (hysteresis/eddy) and copper (resistance) — efficiency matters at scale."],"qa":[["Why do transformers hum?","Magnetostriction: the core physically vibrates at line frequency."],["Step-up vs. step-down?","More secondary turns steps up voltage; fewer steps down — power (minus losses) is conserved."],["Why laminate cores?","Thin insulated layers break up eddy currents that would waste power as heat."]],"title":"Transformers","uses":["Stepping grid voltage to usable levels.","Isolating circuits for safety.","Matching impedances in audio and RF."]},{"brief":"Crystals and oscillators provide precise frequencies — the heartbeat timing every digital circuit runs on.","examples":["A 16MHz crystal clocks an Arduino.","A 32.768kHz tuning-fork crystal keeps a watch's time."],"history":["Quartz piezoelectricity (1880); crystal oscillators stabilized radio in the 1920s-30s.","TCXOs and MEMS oscillators brought precision to phones and GPS."],"points":["Quartz vibrates at a precise frequency when electrified — the piezoelectric effect.","Specs: frequency, tolerance (ppm), stability over temperature, and load capacitance.","32.768kHz = 2^15 Hz — watch crystals divide neatly to one-second ticks.","MEMS oscillators now rival quartz in tiny, shock-proof packages."],"qa":[["What is ppm?","Parts per million frequency error — 20ppm is ~10 minutes/year drift."],["Crystal vs. oscillator?","A crystal is the raw resonator needing external circuitry; an oscillator is the complete module."],["Why 32.768kHz?","It's 2^15 Hz — binary counters divide it exactly to 1Hz for clocks."]],"title":"Crystals and Oscillators","uses":["Clocking processors and microcontrollers.","Keeping time in watches and RTCs.","Generating radio frequencies."]},{"brief":"Fuses and circuit protection sacrifice themselves (or trip) to save the circuit — the last line of defense against faults.","examples":["A 5A fuse blows instead of letting a short melt wiring.","A PTC resettable fuse protects USB ports and resets itself."],"history":["Fuses are 19th century; circuit breakers brought resettability.","Polymeric PTC fuses (1980s) made self-resetting protection cheap."],"points":["Fuses: a calibrated weak link that melts on overcurrent — fast or slow-blow by design.","Breakers: resettable electromechanical protection for buildings and panels.","PTC fuses: resistance spikes when hot, resets when cool — ideal for ports.","TVS diodes and MOVs clamp voltage spikes; fuses handle current."],"qa":[["Fast vs. slow-blow?","Fast for semiconductors; slow-blow tolerates motor startup surges."],["Why did my fuse blow?","Overcurrent from a fault — replacing without finding the cause just blows another."],["What is a TVS diode?","Transient Voltage Suppressor — clamps spikes in nanoseconds to protect inputs."]],"title":"Fuses and Circuit Protection","uses":["Preventing fires from electrical faults.","Protecting inputs from surges and spikes.","Making products safe and certifiable."]},{"brief":"Potentiometers are adjustable resistors — knobs and sliders that divide voltage for user control.","examples":["A volume knob is a potentiometer dividing the audio signal.","A trimmer pot calibrates a sensor circuit at the factory."],"history":["Wirewound pots are early 20th century; carbon and cermet tracks made them cheap.","Digital potentiometers (1990s+) brought software-controlled adjustment."],"points":["Three terminals: the wiper taps anywhere along the resistive track.","Linear vs. logarithmic (audio) taper — human hearing needs log response.","Trimmer pots are set-and-forget calibration; panel pots are user controls.","Digital pots replace knobs with I2C-controlled resistance for automated systems."],"qa":[["How does a volume knob work?","As a voltage divider: the wiper picks a fraction of the signal to pass on."],["Linear vs. log taper?","Linear tracks position evenly; log (audio) matches human perception."],["What is a rheostat?","A two-terminal variable resistor — a pot wired to vary resistance, not divide voltage."]],"title":"Potentiometers","uses":["Volume, brightness, and speed controls.","Factory calibration trimmers.","Position sensing in joysticks."]},{"brief":"Displays (LCD, OLED, e-paper) turn electrical signals into visible information — the face of every device.","examples":["An OLED phone screen lights each pixel individually for perfect blacks.","A 16x2 LCD shows sensor readings on a gadget."],"history":["LCDs (1970s) replaced CRTs; LED backlights then OLED (2010s) transformed screens.","E-paper (2000s) brought paper-like reading to e-readers."],"points":["LCD: liquid crystals modulate a backlight — efficient but blacks glow.","OLED: each pixel emits its own light — perfect blacks, flexible screens.","E-paper: bistable — power only to change, readable in sunlight.","Interfaces: parallel, SPI, I2C for small displays; MIPI/DisplayPort for big ones."],"qa":[["LCD vs. OLED?","LCD is cheaper and brighter; OLED has perfect contrast and flexibility."],["What is burn-in?","Uneven OLED aging from static images — mitigated with pixel shifting."],["How are displays driven?","Controller chips translate digital data into the panel's signals — often over SPI/I2C for small ones."]],"title":"Displays (LCD/OLED)","uses":["Showing information on every device.","Building instruments and dashboards.","Reading books on e-paper."]},{"brief":"Batteries and power components store and deliver electrical energy — the chemistry and circuitry behind portable everything.","demo":{"kind":"runnable-program","note":"Run with: node demo.js — estimate battery life from capacity and load.","program":"// Battery life estimator — run with: node demo.js\nfunction hours(mAh, mA) { return mAh / mA; }\n[\n  { cap: 3000, load: 150, what: 'phone (active)' },\n  { cap: 3000, load: 15, what: 'phone (idle)' },\n  { cap: 2500, load: 50, what: 'sensor node' }\n].forEach(function(c) {\n  console.log(c.what + ':', hours(c.cap, c.load).toFixed(1), 'hours');\n});"},"examples":["A phone's Li-ion cell delivers 3000mAh at 3.7V.","A BMS protects the pack from overcharge and over-discharge."],"history":["Volta's pile (1800); lead-acid (1859); alkaline (1950s); Li-ion (1991) enabled mobile computing.","Battery management systems became essential as energy densities rose."],"points":["Chemistries: Li-ion (energy dense), LiFePO4 (safe, long-lived), NiMH, lead-acid (cheap, heavy).","Capacity (mAh/Wh) is energy; C-rate is how fast it can be drawn — both matter.","BMS: the guardian circuit preventing overcharge, over-discharge, and thermal runaway.","Charging profiles are chemistry-specific — wrong chargers destroy cells."],"qa":[["What is mAh?","Milliamp-hours: how much current for how long — 3000mAh gives 300mA for 10 hours."],["Why do batteries swell?","Gas from electrolyte breakdown — stop using swollen cells immediately."],["What is thermal runaway?","Self-accelerating overheating — the fire risk that BMS designs prevent."]],"title":"Batteries and Power","uses":["Powering portable electronics.","Storing renewable energy.","Running EVs and backup systems."]},{"brief":"Electric motors convert electricity to motion — spinning everything from phone vibrators to trains.","examples":["A drone's brushless motors spin propellers at 20,000 RPM.","A washing machine's motor reverses the drum precisely."],"history":["Faraday's motor (1821); Tesla's AC induction motor (1888) electrified industry.","Brushless motors (1960s+) brought efficiency to everything portable."],"points":["DC brushed: simple, cheap, but brushes wear. Brushless: efficient, long-lived, needs a controller.","Steppers move in precise increments — 3D printers and CNC. Servos add position feedback.","Key specs: voltage, no-load RPM, stall torque, and efficiency.","Drivers matter: H-bridges reverse DC motors; ESCs commutate brushless ones."],"qa":[["Brushed vs. brushless?","Brushed is simple with wearing contacts; brushless is efficient and durable but needs electronics."],["What is stall torque?","The torque at zero speed — the maximum force before the motor can't turn."],["How do you reverse a motor?","Reverse polarity (DC) or phase order (AC/brushless) — H-bridges do it electronically."]],"title":"Motors (Electric)","uses":["Driving robots, drones, and appliances.","Positioning precisely with steppers and servos.","Powering EVs and industry."]},{"brief":"Fasteners — screws, bolts, nuts, washers — hold the mechanical world together, each type engineered for specific loads and materials.","demo":{"kind":"runnable-program","note":"Run with: node demo.js — pick fastener specs by load.","program":"// Fastener picker — run with: node demo.js\nvar fasteners = [\n  { type: 'M3 machine screw', shear: 1200, use: 'electronics' },\n  { type: 'M6 bolt', shear: 7500, use: 'frames' },\n  { type: 'M12 bolt', shear: 30000, use: 'structural' }\n];\nfunction pick(loadN) {\n  for (var i = 0; i < fasteners.length; i++)\n    if (fasteners[i].shear > loadN * 4) return fasteners[i];\n  return { type: 'custom engineering', use: 'consult a table' };\n}\n[500, 5000, 20000, 200000].forEach(function(l) {\n  console.log(l + 'N load ->', pick(l).type);\n});"},"examples":["M3 screws assemble electronics; M12 bolts hold structural steel.","A lock washer keeps a vibrating assembly from loosening."],"history":["Standardized screw threads (Whitworth 1841, then metric) made parts interchangeable.","The fastener industry became the quiet backbone of mass production."],"points":["Screws thread into material; bolts pass through and take a nut — different joints, different rules.","Grades mark strength: a Grade 8.8 bolt vastly out-holds a 4.6 — match grade to load.","Washers spread load and lock against vibration; threadlocker fluid does it chemically.","Torque specs exist for a reason: under-torqued loosens, over-torqued strips or snaps."],"qa":[["Screw vs. bolt?","Screws cut their own path into material; bolts clamp through holes with nuts."],["What is thread pitch?","The distance between threads — coarse for soft materials, fine for hard ones and adjustment."],["Why do bolts loosen?","Vibration walks threads backward — locking washers, nuts, or threadlocker prevent it."]],"title":"Fasteners (Screws, Bolts, Nuts)","uses":["Assembling everything from phones to bridges.","Enabling disassembly for repair and maintenance.","Standardizing joints across industries."]},{"brief":"Bearings let shafts spin freely — rolling elements between races that turn sliding friction into rolling ease.","examples":["Skateboard wheels spin on 608 bearings.","A wind turbine's main bearing carries tons while turning slowly."],"history":["Rolling bearings date to antiquity; modern precision bearings enabled the industrial revolution.","Sealed, lubricated-for-life bearings in the 20th century cut maintenance drastically."],"points":["Types: ball (fast, light), roller (heavy radial), needle (compact), thrust (axial loads).","Ratings: dynamic (rotating life) and static (standing load) — in newtons.","Lubrication is life: grease for most, oil for high speed — dry bearings die fast.","Seals keep dirt out and grease in; contamination is the #1 killer."],"qa":[["What is ABEC?","A precision rating scale — higher means tighter tolerances, not automatically 'better' for every use."],["Why do bearings fail?","Contamination, overload, and lubrication failure — in that order."],["Ball vs. roller?","Balls for speed and light loads; rollers for heavy loads at moderate speeds."]],"title":"Bearings","uses":["Supporting rotating shafts in motors and wheels.","Enabling precision spindles and turbines.","Cutting friction everywhere things turn."]},{"brief":"Gears transmit rotation between shafts — changing speed, torque, and direction with toothed precision.","demo":{"kind":"runnable-program","note":"Run with: node demo.js — compute gear-train speed and torque.","program":"// Gear train calculator — run with: node demo.js\nfunction train(teeth) {\n  var ratio = 1, out = [];\n  for (var i = 0; i < teeth.length - 1; i++) {\n    var r = teeth[i + 1] / teeth[i];\n    ratio *= r;\n    out.push(teeth[i] + '->' + teeth[i + 1] + ' x' + r.toFixed(2));\n  }\n  return { stages: out, totalRatio: ratio };\n}\nvar t = train([12, 36, 12, 48]);\nconsole.log(t.stages.join(', '));\nconsole.log('12 RPM in ->', (12 / t.totalRatio).toFixed(1), 'RPM out, torque x' + t.totalRatio.toFixed(1));"},"examples":["A bicycle's gears trade speed for hill-climbing torque.","A gearbox reduces a motor's 3000 RPM to a wheel's 300 RPM."],"history":["Gears are ancient (Antikythera mechanism); involute teeth (18th century) made them smooth and standard.","Modern hobbing and grinding produce near-silent precision gears."],"points":["Ratio = driven teeth / driver teeth: more teeth driven means slower but stronger.","Types: spur (parallel shafts), helical (quieter), bevel (angled), worm (huge reduction).","Meshing needs matched modules (tooth size) and proper backlash — not too tight, not loose.","Lubrication and alignment determine whether gears whisper or scream."],"qa":[["What is gear ratio?","Driven teeth divided by driver teeth — the speed reduction and torque multiplication."],["Why helical over spur?","Gradual tooth engagement runs quieter and handles more load."],["What is backlash?","The tiny play between meshing teeth — needed for lubrication, harmful in precision drives."]],"title":"Gears","uses":["Trading speed for torque in transmissions.","Changing rotation direction and shaft angles.","Timing engines and machines precisely."]},{"brief":"Springs store and release mechanical energy — pushing, pulling, and cushioning across every machine.","examples":["A car suspension spring absorbs bumps.","A clothespin's torsion spring holds it shut."],"history":["Springs are prehistoric (bows); coiled steel springs enabled the industrial age.","Modern alloys and simulation perfected spring design."],"points":["Hooke's Law: force = stiffness × displacement — linear within the elastic range.","Types: compression, extension, torsion, and leaf — each loaded differently.","Fatigue is the killer: springs survive millions of cycles below their endurance limit.","Spring rate (N/mm) is the spec that matters — force per unit of deflection."],"qa":[["What is spring rate?","Stiffness: how much force per millimeter of compression — the key sizing number."],["Why do springs break?","Fatigue from cyclic stress, corrosion pitting, or overstressing past yield."],["What is Hooke's Law?","F = kx: force proportional to displacement, within the elastic limit."]],"title":"Springs","uses":["Absorbing shocks in suspensions.","Returning mechanisms to position.","Storing energy in toys and tools."]},{"brief":"Seals and gaskets keep fluids in and contaminants out — the unsung barriers in every engine, pump, and pipe.","examples":["An O-ring seals a hydraulic fitting at 200 bar.","A head gasket seals combustion pressure between engine block and head."],"history":["Leather and rope seals are ancient; rubber O-rings (1930s) standardized sealing.","PTFE and modern elastomers extended seals to chemicals and extremes."],"points":["O-rings: the universal seal — cheap, effective, sized by groove standards.","Gaskets seal flat flanges; choose material for fluid, temperature, and pressure.","Dynamic seals (rotating shafts) are harder than static — lip seals and mechanical seals.","Installation matters: a nicked O-ring or dirty flange leaks regardless of quality."],"qa":[["How do you size an O-ring?","By groove dimensions per standards (Parker, metric) — squeeze, not stretch, seals."],["What kills seals?","Wrong material for the fluid, excessive heat, and installation damage."],["Gasket vs. seal?","Gaskets seal static flat joints; seals is the broader term including dynamic ones."]],"title":"Seals and Gaskets","uses":["Containing pressure in hydraulics and engines.","Keeping water, dust, and chemicals out.","Enabling pumps, valves, and piping."]},{"brief":"Belts and chains transmit power between distant shafts — flexible, forgiving, and everywhere from bikes to factories.","examples":["A car's serpentine belt drives alternator, pump, and AC.","A bicycle chain links pedals to the rear wheel."],"history":["Leather belts drove 19th-century factories from central steam engines.","Timing belts (1940s+) brought precision to engine valve trains."],"points":["Belts: quiet, clean, no lubrication — but they slip and stretch.","Chains: positive drive, no slip — but need lubrication and are noisier.","Timing belts synchronize precisely (engine valves); V-belts just transmit power.","Tension is critical: too loose slips, too tight kills bearings."],"qa":[["Belt vs. chain?","Belts for quiet cleanliness; chains for positive no-slip drive under load."],["What is a timing belt?","A toothed belt keeping crankshaft and camshaft synchronized — breakage can destroy engines."],["Why do belts squeal?","Slip from looseness, wear, or contamination — tension and condition fix it."]],"title":"Belts and Chains","uses":["Driving accessories from engines.","Transmitting pedal power on bicycles.","Synchronizing machine timing."]},{"brief":"Shafts are the rotating backbones of machines — transmitting torque between components with precision-ground strength.","examples":["A motor shaft couples to a pump through a flexible coupling.","A driveshaft carries engine power to the wheels."],"history":["Line shafts powered whole 19th-century factories from one engine.","Precision grinding made modern high-speed shafts possible."],"points":["Shafts carry torque and bending loads — sized by strength and stiffness.","Keyways, splines, and flats lock components against rotation.","Critical speed: every shaft has resonant RPMs to avoid — vibration destroys.","Surface finish matters: seals and bearings need smooth, hard journals."],"qa":[["What is critical speed?","The RPM where a shaft resonates — running there causes violent vibration."],["Keyway vs. spline?","Keyways use one key for light duty; splines use many teeth for heavy torque."],["Why do shafts fail?","Fatigue at stress risers (keyways, shoulders) — smooth transitions extend life."]],"title":"Shafts","uses":["Transmitting power through machines.","Carrying gears, pulleys, and rotors.","Linking motors to loads."]},{"brief":"Couplings join two shafts — rigidly for precision or flexibly to forgive misalignment.","examples":["A jaw coupling connects a motor to a pump, absorbing vibration.","A universal joint lets a driveshaft bend with suspension travel."],"history":["Rigid couplings are ancient; flexible elastomer couplings came with modern machinery.","Universal joints (Cardan, 16th century) solved angled drive elegantly."],"points":["Rigid couplings demand perfect alignment; flexible ones tolerate angular and parallel offset.","Elastomer spiders absorb shock and damp vibration — the most common flexible type.","Universal joints handle large angles but introduce speed fluctuation — CV joints fix that.","Guards are mandatory: exposed couplings grab clothing and limbs."],"qa":[["Why not always rigid?","Because real shafts misalign — rigid couplings then destroy bearings."],["What is misalignment?","Angular, parallel, or axial offset between shafts — flexible couplings absorb limited amounts."],["How much misalignment is okay?","Per the coupling's rating — measure with dial indicators, don't guess."]],"title":"Couplings","uses":["Joining motors to driven equipment.","Absorbing misalignment and vibration.","Protecting drivetrains with sacrificial elements."]},{"brief":"Valves control fluid flow — opening, closing, and throttling liquids and gases across every process.","examples":["A ball valve shuts off water with a quarter turn.","A pressure-relief valve vents before a tank bursts."],"history":["Valves are ancient (Roman plumbing); the industrial age standardized gate, globe, and ball designs.","Solenoid valves (20th century) brought electrical control."],"points":["Ball valves: quarter-turn, full-bore, best for on/off. Globe: precise throttling. Check: one-way flow.","Relief valves are safety devices — sized and set to protect vessels, not processes.","Actuation: manual, pneumatic, electric, solenoid — matched to speed and force needs.","Seals and seats wear: match materials to fluid chemistry and temperature."],"qa":[["Ball vs. gate vs. globe?","Ball for quick on/off, gate for minimal restriction, globe for throttling control."],["What is Cv?","The flow coefficient — how much flows per pressure drop; the sizing number."],["Why do valves leak?","Worn seats, wrong materials, or debris — maintenance and correct selection prevent it."]],"title":"Valves","uses":["Controlling flow in plumbing and process plants.","Protecting vessels with relief valves.","Automating fluid control with solenoids."]},{"brief":"Pumps move fluids — water, oil, chemicals — against pressure, the workhorses of industry and infrastructure.","examples":["A centrifugal pump circulates heating water through a building.","A peristaltic pump doses chemicals precisely without contamination."],"history":["Pumps are ancient (Archimedes' screw); centrifugal pumps (17th century) dominate today.","Positive-displacement designs handle viscous and precise duties."],"points":["Centrifugal: high flow, moderate pressure — the default for water.","Positive displacement (gear, diaphragm, peristaltic): precise flow regardless of pressure.","Cavitation — vapor bubbles collapsing — destroys pumps; keep suction flooded.","Seals are the wear point: match to fluid and maintain."],"qa":[["What is cavitation?","Vapor bubbles forming and collapsing in the pump — noisy, destructive erosion."],["Centrifugal vs. positive displacement?","Centrifugal for bulk flow; PD for precise metering and thick fluids."],["What is head?","The height (pressure) a pump can lift fluid — the sizing number alongside flow."]],"title":"Pumps","uses":["Moving water through buildings and cities.","Dosing chemicals precisely.","Circulating coolant and lubricants."]},{"brief":"Actuators convert energy into motion — electric, hydraulic, or pneumatic muscles that move valves, arms, and machines.","examples":["A linear actuator opens a greenhouse vent as temperature rises.","Servo actuators position a robot arm precisely."],"history":["Hydraulic actuators powered industrial machinery; electric servos brought precision in the 20th century.","Smart actuators with feedback became standard in automation."],"points":["Types: linear (push/pull), rotary (spin), each in electric/hydraulic/pneumatic flavors.","Key specs: force/torque, speed, stroke, duty cycle, and precision.","Electric: clean and precise. Hydraulic: immensely strong. Pneumatic: fast and simple.","Feedback (encoders, limit switches) turns dumb motion into controlled positioning."],"qa":[["Actuator vs. motor?","Motors spin continuously; actuators produce controlled motion, often linear or limited-travel."],["What is duty cycle?","How long it can run versus rest — overheating kills overworked actuators."],["How do you size one?","Force, speed, and stroke for the load — with safety margin for friction and inertia."]],"title":"Actuators","uses":["Automating valves, dampers, and doors.","Positioning robots and machines.","Converting control signals to physical action."]},{"brief":"Antennas convert between electrical signals and radio waves — the ears and mouths of wireless everything.","examples":["A phone's antennas handle cellular, Wi-Fi, Bluetooth, and GPS.","A dish antenna focuses satellite signals from orbit."],"history":["Hertz (1880s) proved radio; Marconi's antennas spanned oceans by 1901.","Fractal and MIMO antennas in the 2000s-2010s packed performance into phones."],"points":["Resonance: antennas work best near wavelengths matching their size — hence 2.4GHz Wi-Fi antennas ~3cm.","Gain focuses energy directionally; omnidirectional radiates everywhere.","VSWR measures matching: poor match reflects power back and heats transmitters.","MIMO uses multiple antennas for speed — modern Wi-Fi and 5G depend on it."],"qa":[["What is antenna gain?","Focus: how much stronger the signal is in the favored direction versus isotropic."],["Why are phone antennas hidden?","Miniaturization and aesthetics — modern designs integrate them into frames."],["What is VSWR?","Voltage Standing Wave Ratio — how well the antenna matches its feedline; lower is better."]],"title":"Antennas","uses":["Connecting phones, Wi-Fi, and IoT wirelessly.","Broadcasting radio and television.","Linking satellites to ground stations."]},{"brief":"Voltage regulators hold output voltage steady despite input and load changes — the guardians of clean power.","examples":["A 7805 regulator turns 9V into clean 5V for logic circuits.","A buck converter efficiently steps 12V down to 3.3V."],"history":["Zener references then linear regulators (1960s-70s); switching regulators took over for efficiency.","Modern PMICs integrate many regulators for phones."],"points":["Linear regulators: simple, quiet, but burn excess as heat — fine for small drops.","Switching regulators (buck/boost): efficient (90%+) but noisier — the modern default.","LDOs regulate with tiny input-output margins for battery-powered designs.","Specs: dropout voltage, current limit, thermal shutdown, and output accuracy."],"qa":[["Linear vs. switching?","Linear for simplicity and low noise; switching for efficiency at larger drops."],["What is dropout?","The minimum input-output difference a regulator needs — LDOs work with millivolts."],["Why do regulators get hot?","Linear types dissipate (Vin-Vout)×I as heat — heatsink or switch instead."]],"title":"Voltage Regulators","uses":["Powering logic from higher-voltage supplies.","Cleaning noisy power for sensitive analog circuits.","Managing phone power with integrated PMICs."]},{"brief":"Microcontrollers are computers on a chip — CPU, memory, and peripherals integrated for embedded control.","examples":["An Arduino's ATmega328 blinks LEDs and reads sensors.","A car's dozens of MCUs manage engine, brakes, and windows."],"history":["The 8048 (1976) and PIC/AVR lines made MCUs ubiquitous; Arduino (2005) democratized them.","32-bit ARM MCUs now cost pennies with serious performance."],"points":["Integrated: flash, RAM, timers, ADC, and serial peripherals on one die.","Choose by pins, peripherals, power, and ecosystem — not just megahertz.","Bare-metal C or MicroPython: control down to the register or comfort of scripting.","Low-power modes sip microamps — essential for battery devices."],"qa":[["MCU vs. CPU?","MCUs integrate memory and peripherals for control; CPUs maximize compute with external everything."],["What is an ADC?","Analog-to-Digital Converter — reading real-world voltages into numbers."],["Arduino vs. bare MCU?","Arduino is the friendly ecosystem; bare MCUs are the same silicon without training wheels."]],"title":"Microcontrollers","uses":["Controlling appliances, toys, and gadgets.","Reading sensors and driving actuators in IoT.","Teaching embedded programming hands-on."]},{"brief":"Memory chips store data and code — RAM for working space, ROM/flash for permanence — the recall of every computer.","examples":["An MCU's flash holds firmware; its SRAM holds variables.","An SSD's NAND flash stores terabytes persistently."],"history":["Core memory gave way to DRAM (1970s); flash (1980s) made storage solid-state.","3D NAND in the 2010s stacked memory vertically to keep scaling."],"points":["Volatile (SRAM/DRAM) forgets without power; non-volatile (flash/EEPROM) remembers.","SRAM is fast and pricey (caches); DRAM is dense and cheap (main memory).","Flash wears out with writes — wear leveling spreads the load.","Specs: capacity, speed, endurance (write cycles), and interface."],"qa":[["RAM vs. flash?","RAM is fast working memory (volatile); flash is persistent storage (slower, wears)."],["What is wear leveling?","Distributing writes across flash cells so none wears out early."],["Why is RAM volatile?","Its storage mechanism (capacitors/flip-flops) needs continuous power."]],"title":"Memory Chips (RAM/ROM/Flash)","uses":["Holding firmware permanently in flash.","Providing working memory for programs.","Storing data in SSDs and cards."]},{"brief":"Optocouplers transfer signals via light across an isolation barrier — control without electrical connection.","examples":["An optocoupler lets a microcontroller sense 240V mains safely.","Isolated gate drivers protect control logic from motor noise."],"history":["Optocouplers matured in the 1970s for industrial isolation.","High-speed digital isolators now complement them."],"points":["An LED shines on a phototransistor inside one package — light bridges the gap.","Isolation ratings (kV) define the safety barrier — critical for mains interfaces.","CTR (current transfer ratio) measures efficiency of the light link.","Use where grounds differ or safety demands separation."],"qa":[["Why isolate?","To protect low-voltage logic from high-voltage faults and break ground loops."],["What is CTR?","Current Transfer Ratio — output current per input current through the optical link."],["Optocoupler vs. transformer?","Optocouplers pass DC-capable signals cheaply; transformers handle power and AC."]],"title":"Optocouplers","uses":["Sensing mains voltage safely.","Isolating noisy power stages from logic.","Breaking ground loops in audio and data."]},{"brief":"Buzzers and speakers turn electrical signals into sound — alerts, alarms, and audio output.","examples":["A piezo buzzer beeps on button presses.","A speaker plays music from an amplifier."],"history":["Buzzers are 19th century; dynamic speakers (1920s) brought hi-fi.","Piezo elements made tiny, efficient sounders for electronics."],"points":["Piezo buzzers: efficient beeps from AC drive — the classic alert.","Magnetic buzzers and speakers need more drive but sound fuller.","Active buzzers beep on DC; passive need a waveform — know which you have.","Volume follows drive voltage and enclosure — a box makes a buzzer loud."],"qa":[["Active vs. passive buzzer?","Active beeps with just DC power; passive needs an AC/tone signal."],["How do speakers work?","A coil in a magnetic field moves a cone with the audio signal — air becomes sound."],["Why so quiet?","Undriven piezos are faint — proper voltage and a resonant cavity help."]],"title":"Buzzers and Speakers","uses":["Alerting users with beeps and alarms.","Playing audio in devices.","Signaling status without a display."]},{"brief":"Heat sinks are passive thermal components — finned metal that spreads heat from hot parts into the air.","examples":["A CPU cooler keeps a processor under its thermal limit.","An LED streetlight's housing is one big heat sink."],"history":["Heat sinks grew with power electronics; heat pipes (1960s) moved heat efficiently.","Modern designs are simulation-optimized for airflow."],"points":["Fins multiply surface area — more area, more heat transfer to air.","Thermal paste fills microscopic gaps between chip and sink — never skip it.","Natural convection works for small loads; fans multiply capacity.","Thermal resistance (°C/W) is the spec: lower means cooler for the same power."],"qa":[["Do I need a heat sink?","If the part's dissipation × thermal resistance exceeds its temperature limit — calculate it."],["What is thermal paste?","Conductive compound filling air gaps between chip and sink — air is an insulator."],["Active vs. passive cooling?","Passive is silent and reliable; fans move far more heat when needed."]],"title":"Heat Sinks and Thermal","uses":["Keeping processors and power parts cool.","Enabling reliable high-power electronics.","Silencing designs with passive cooling."]},{"brief":"Software libraries are reusable code collections — packaged functions and classes that solve common problems.","demo":{"kind":"runnable-program","note":"Run with: node demo.js — a tiny library: import once, use everywhere.","program":"// Tiny library — run with: node demo.js\nvar strlib = {\n  capitalize: function(s) { return s.charAt(0).toUpperCase() + s.slice(1); },\n  slug: function(s) { return s.toLowerCase().replace(/[^a-z0-9]+/g, '-'); }\n};\nconsole.log(strlib.capitalize('hello world'));\nconsole.log(strlib.slug('Hello World!'));"},"examples":["A date library handles time zones correctly so you don't have to.","A charting library turns data into interactive graphs."],"history":["Subroutine libraries are 1950s; package managers (2010s) made consuming them trivial.","The modern app is mostly libraries glued with custom logic."],"points":["Libraries are code you call — the inversion of frameworks, which call you.","Evaluate: maintenance, license, size, and API quality before adopting.","Pin versions: libraries evolve, and updates can break you.","Prefer boring and battle-tested for critical paths."],"qa":[["Library vs. framework?","Libraries are tools you wield; frameworks are structures you inhabit."],["How many dependencies is too many?","When you can't audit or update them — keep the tree lean and known."],["What is dependency hell?","Conflicting version demands — lockfiles and careful ranges manage it."]],"title":"Software Libraries","uses":["Reusing proven solutions instead of rewriting.","Accelerating development with tested code.","Standardizing common tasks across projects."]},{"brief":"Frameworks provide the skeleton of an application — structure, conventions, and lifecycle — that developers fill with specific logic.","examples":["A web framework routes requests, renders views, and manages sessions.","A game engine framework handles rendering loops and physics."],"history":["MVC frameworks (2000s) structured web apps; modern frameworks span frontend, mobile, and ML.","The framework decision shapes a project's entire architecture."],"points":["Inversion of control: the framework calls your code at defined extension points.","Conventions accelerate: file placement and naming carry meaning.","Ecosystems matter as much as code: plugins, docs, and hiring pool.","Frameworks trade freedom for velocity — choose the trade deliberately."],"qa":[["When framework over library?","When the problem is well-understood and the framework's structure matches it."],["What is inversion of control?","The framework owns the flow; you plug in handlers — Hollywood principle: don't call us, we'll call you."],["How do you escape a framework?","Slowly — isolate framework code behind your own interfaces from day one."]],"title":"Frameworks","uses":["Structuring applications consistently.","Accelerating standard problem domains.","Leveraging ecosystems and conventions."]},{"brief":"Software modules and packages organize code into distributable units — the building blocks of modern applications.","examples":["An npm package adds authentication with one install command.","A Python wheel distributes a library with compiled extensions."],"history":["Modules formalized in the 1970s; packages and registries exploded in the 2010s.","Semantic versioning tamed the chaos of evolving dependencies."],"points":["A module encapsulates: public interface in, implementation hidden.","Packages bundle modules with metadata: name, version, license, dependencies.","Registries (npm, PyPI) distribute; lockfiles make installs reproducible.","Design for reuse: small surface, clear docs, stable versioning."],"qa":[["Module vs. package?","A module is a code unit; a package is the distributable bundle of modules."],["What is semantic versioning?","MAJOR.MINOR.PATCH — breaking, feature, fix — the compatibility contract."],["Why do packages matter?","They turn rebuilding into composing — modern software is assembled."]],"title":"Modules and Packages (Software)","uses":["Sharing code within and across projects.","Versioning shared functionality independently.","Building on ecosystems instead of from scratch."]},{"brief":"Plugins and extensions let users add capabilities to software without touching its core — the architecture of extensibility.","examples":["Browser extensions add ad-blocking to Chrome.","A CMS plugin adds e-commerce to a blog."],"history":["Plugin architectures date to 1980s applications; app stores (2008) made extensions mainstream.","Marketplaces turned plugins into businesses."],"points":["A stable plugin API is the contract: hooks, filters, and extension points.","Sandboxing protects the host: plugins shouldn't crash or spy on the core.","Version the API: breaking plugin interfaces orphans an ecosystem.","Curate the marketplace: review for security and quality."],"qa":[["Plugin vs. extension?","Overlapping terms — both add capability through defined interfaces."],["Why do plugins break on updates?","Because they depend on internals that changed — stable APIs prevent it."],["Are plugins safe?","Only with sandboxing and review — they run with the host's privileges."]],"title":"Plugins and Extensions","uses":["Customizing software without forking it.","Building ecosystems around a core product.","Monetizing through marketplaces."]},{"brief":"APIs as components treat service interfaces as composable building blocks — Stripe for payments, Twilio for messaging, assembled into products.","examples":["A startup launches with payments, auth, and email all via APIs.","A maps API adds location to any application."],"history":["Web APIs (2000s) then API-first companies (2010s) made services composable.","The API economy: businesses built entirely on others' components."],"points":["Buy vs. build: APIs convert months of work into an integration.","Evaluate SLAs, pricing at scale, and data practices — dependencies are commitments.","Abstract vendors behind interfaces to preserve switching options.","Monitor third-party health: their outage is your outage."],"qa":[["What is API-first?","Designing the interface before the implementation — often as the product itself."],["How do you choose an API?","Docs quality, reliability, pricing trajectory, and exit options."],["What is vendor lock-in?","Dependence that's expensive to escape — mitigated with abstractions."]],"title":"APIs as Components","uses":["Assembling products from best-of-breed services.","Launching faster by buying commodity capabilities.","Scaling without building every subsystem."]},{"brief":"Microservices are independently deployable software components — small services with their own data, communicating over networks.","examples":["An e-commerce site splits catalog, cart, and payments into services.","Teams deploy their service 20 times a day without coordinating."],"history":["SOA (2000s) dreamed it; microservices (2014+) made it practical with containers and DevOps.","The pattern proved itself at web scale, then spread everywhere."],"points":["Bounded contexts: each service owns one business capability and its data.","Independent deployability is the goal — and the test of the decomposition.","Costs: distributed debugging, network latency, and operational overhead.","Start modular-monolith: extract services when boundaries prove themselves."],"qa":[["Microservices vs. monolith?","Microservices optimize independent scaling and deployment; monoliths optimize simplicity and consistency."],["What is a bounded context?","A coherent business area with its own model — the natural service boundary."],["When are microservices wrong?","For small teams and simple domains — the overhead exceeds the benefit."]],"title":"Microservices","uses":["Scaling development across many teams.","Deploying parts independently at high velocity.","Isolating failures to single capabilities."]},{"brief":"Containers as components package software with its dependencies into portable, isolated units — the shipping containers of code.","examples":["A microservice ships as a versioned image running identically everywhere.","CI builds each component's image and tests the composed system."],"history":["Docker (2013) standardized containers; Kubernetes (2014) orchestrated them.","Images became the unit of deployment across the industry."],"points":["Images are immutable: build once, run anywhere — dev matches prod.","Isolation is process-level, not hardware — lighter than VMs, less isolated.","Registries version and distribute images like packages.","Compose systems from images: the architecture is the composition."],"qa":[["Container vs. VM?","Containers share the kernel (light); VMs virtualize hardware (isolated)."],["What is an image?","The immutable template — layers of filesystem plus metadata — containers instantiate."],["Are containers secure?","Reasonably isolated; harden images and scan for vulnerabilities."]],"title":"Containers as Components","uses":["Deploying consistently across environments.","Composing systems from versioned images.","Scaling components independently."]},{"brief":"UI widgets are reusable interface components — buttons, inputs, tables — the Lego bricks of user interfaces.","examples":["A date-picker widget used across fifty forms.","A data table with sorting, filtering, and pagination built once."],"history":["GUI toolkits (1980s-90s) pioneered widgets; web component libraries (2010s) standardized them.","Design systems turned widgets into brand-consistent sets."],"points":["Props in, events out: widgets are functions of their inputs.","Accessibility is non-negotiable: keyboard, screen reader, and contrast support.","Style via themes and tokens, not hardcoded values.","Test interactions, not just rendering: the widget's contract is behavioral."],"qa":[["What makes a good widget?","Clear props, predictable events, accessibility, and theming support."],["Build vs. buy widgets?","Buy commodity (date pickers), build differentiating (core workflows)."],["What is a design token?","Named style values (colors, spacing) shared between design and code."]],"title":"UI Widgets","uses":["Building consistent interfaces fast.","Ensuring accessibility across products.","Sharing UI across teams and apps."]},{"brief":"Design systems are the complete component sets — widgets, tokens, patterns, and guidance — that keep products coherent at scale.","examples":["A company's design system powers fifty products with one visual language.","Tokens propagate a rebrand to every app automatically."],"history":["Style guides are old; design systems (2010s) made them living code.","Tokens (2020s) separated design decisions from implementations."],"points":["Components plus tokens plus documentation: the system is the trio.","Governance decides what enters: contribution models keep quality high.","Version carefully: breaking changes ripple to every consumer.","Measure adoption: a system nobody uses is just a website."],"qa":[["What is a design token?","A named design decision shared as data between design tools and code."],["Who maintains a design system?","A dedicated team with a contribution model."],["How do you measure success?","Adoption rate, contribution velocity, and consistency scores."]],"title":"Design Systems","uses":["Unifying product families visually.","Accelerating teams with proven patterns.","Rebranding systematically via tokens."]},{"brief":"Middleware components sit between systems — translating, routing, and enriching — the plumbing of integration.","examples":["An API gateway routes and authenticates requests to microservices.","Message brokers queue work between producers and consumers."],"history":["Enterprise service buses (2000s) centralized integration; lightweight middleware (2010s) distributed it.","Service meshes now handle service-to-service concerns transparently."],"points":["Functions: routing, transformation, protocol bridging, and cross-cutting concerns.","Don't build a smart-pipe monolith: keep middleware dumb, endpoints smart.","Observability through middleware: centralized logging of distributed flows.","Choose boring middleware: exotic integration tech becomes the bottleneck."],"qa":[["What is middleware?","Software connecting software — handling communication between components."],["ESB vs. modern approaches?","Centralized buses vs. decentralized smart endpoints — the industry moved decentralized."],["When is middleware needed?","When systems must integrate without direct coupling — which is most of the time."]],"title":"Middleware","uses":["Integrating disparate systems.","Handling cross-cutting communication concerns.","Observing distributed flows centrally."]},{"brief":"Package registries are the distribution hubs for software components — npm, PyPI, Maven Central — where the world's code is published.","examples":["npm install pulls a package and its tree in seconds.","A private registry hosts a company's internal components."],"history":["CPAN (1995) pioneered registries; npm (2010) scaled to millions of packages.","Supply-chain attacks in the 2020s made registry security critical."],"points":["Registries index, version, and serve packages with metadata and signatures.","Lockfiles pin exact trees; registries guarantee the bytes.","Private registries host proprietary components with access control.","Verify signatures and provenance — registries are attack targets."],"qa":[["What is package provenance?","Cryptographic proof of where a package was built — fighting supply-chain attacks."],["Public vs. private registries?","Public for open source; private for proprietary code with access control."],["What happens if a registry is down?","Builds break — mirror critical registries for resilience."]],"title":"Package Registries","uses":["Distributing components to the world.","Securing the software supply chain.","Hosting private organizational code."]},{"brief":"The future of components spans chiplets, printed electronics, and AI-designed parts — smaller, smarter, and more integrated.","examples":["Chiplet designs mix-and-match silicon for custom processors.","Printed sensors enable disposable smart packaging."],"history":["Integration marched from boards to chips to systems-in-package.","The next leaps are heterogeneous integration and sustainable materials."],"points":["Chiplets: specialized silicon tiles composed into custom systems.","Sustainable components: biodegradable substrates and conflict-free materials.","AI-designed parts: topology optimization beyond human intuition.","The trend: more function per volume, less energy per function."],"qa":[["What are chiplets?","Small specialized dies packaged together — mixing logic, memory, and I/O optimally."],["Will components disappear into software?","Some already have (software-defined radio); physics keeps the rest."],["What's the sustainability angle?","Longer-lived, repairable, recyclable components — regulation is coming."]],"title":"The Future of Components","uses":["Planning for chiplet-based designs.","Adopting sustainable component choices.","Leveraging AI in component design."]}];
function buildContent(t,angle){
  var title=t.title,brief=t.brief,pts=t.points,exs=t.examples,his=t.history,uses=t.uses,qa=t.qa;
  var summary,sections,key_facts,i,rest;
  if(angle==='overview'){
    summary=brief+' This overview covers the essentials of '+title+': what it is, why it matters, and where it is used.';
    sections=[{heading:'What it is',body:brief+' '+pts.slice(0,2).join(' ')},{heading:'Key points',body:pts.join(' ')},{heading:'Why it matters',body:uses.slice(0,2).join(' ')}];
    key_facts=pts;
  }else if(angle==='detailed'){
    rest=pts.slice(2);
    summary='A detailed examination of '+title+'. '+brief;
    sections=[{heading:'Core details',body:pts.slice(0,3).join(' ')},{heading:'Going deeper',body:rest.length?rest.join(' '):pts.join(' ')},{heading:'Background and context',body:his.slice(0,2).join(' ')},{heading:'Where it is used',body:uses.join(' ')}];
    key_facts=pts;
  }else if(angle==='examples'){
    summary='Illustrative examples of '+title+' in practice. '+brief;
    sections=[];for(i=0;i<exs.length;i++)sections.push({heading:'Example '+(i+1),body:exs[i]});
    key_facts=pts.slice(0,3);
  }else if(angle==='faq'){
    summary='Frequently asked questions about '+title+'. '+brief;
    sections=[];for(i=0;i<qa.length;i++)sections.push({heading:'Q: '+qa[i][0],body:'A: '+qa[i][1]});
    key_facts=pts.slice(0,3);
  }else if(angle==='history'){
    summary='The background and development of '+title+'. '+brief;
    sections=[];for(i=0;i<his.length;i++)sections.push({heading:'Milestone '+(i+1),body:his[i]});
    key_facts=pts.slice(0,3);
  }else{
    summary='Practical applications of '+title+'. '+brief;
    sections=[];for(i=0;i<uses.length;i++)sections.push({heading:'Application '+(i+1),body:uses[i]});
    key_facts=pts.slice(0,3);
  }
  return{summary:summary,sections:sections,key_facts:key_facts};
}
function defaultDemo(){
  return{kind:'record-program',
    program:"// record card — run with: node demo.js\n// (place the record JSON next to this file as record.json)\nconst card = JSON.parse(require('fs').readFileSync('record.json', 'utf8'));\nconsole.log(card.id + ' — ' + card.title + ' [' + card.src + ']');",
    note:'A runnable program card for this record. Save as demo.js, save the record JSON as record.json beside it, and run with node.'};
}
function generate(seed,opts){
  opts=opts||{};
  var s=(seed>>>0)||1;
  var ti=(((s-1)/6)|0)%TOPICS.length, ai=(s-1)%6;
  var angle=ANGLES[ai];
  if(opts.genre&&ANGLES.indexOf(opts.genre)>=0)angle=opts.genre;
  var t=TOPICS[ti],title=t.title,brief=t.brief,topic=t;
  var ctopic=opts.topic?String(opts.topic).trim().slice(0,120):'';
  if(ctopic){title=ctopic;brief='A user-requested '+RECORD_KIND+' on "'+ctopic+'".';
    topic={title:title,brief:brief,points:t.points,examples:t.examples,history:t.history,uses:t.uses,qa:t.qa,demo:t.demo};}
  var id=PREFIX+pad(s);
  var content=buildContent(topic,angle);
  var demo=topic.demo||defaultDemo();
  return{id:id,title:title+' ('+angle+')',description:brief+' This '+angle+' guide provides comprehensive coverage.',genre:angle,type:RECORD_KIND,content:content,demo:demo,src:SRC,_seed:s};
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return{ok:false,errors:['not an object']};
  if(typeof r.id!=='string'||r.id.indexOf(PREFIX)!==0||!/\d{6}$/.test(r.id))e.push('id');
  if(typeof r.title!=='string'||r.title.length<8)e.push('title');
  if(typeof r.description!=='string'||r.description.length<40)e.push('description');
  if(ANGLES.indexOf(r.genre)<0)e.push('genre');
  if(!r.content||typeof r.content!=='object'||typeof r.content.summary!=='string'||r.content.summary.length<40)e.push('content');
  if(!r.demo||typeof r.demo!=='object')e.push('demo');
  return{ok:!e.length,errors:e};
}
function driftCheck(rec,sample){
  for(var i=0;i<sample.length;i++){if(sample[i]&&sample[i].t===rec.title)return{ok:false,errors:['duplicate title in archive sample']};}
  return{ok:true,errors:[]};
}
var gen={version:'jahdb-components-generator-1.0',generate:generate,validate:validate,driftCheck:driftCheck,genres:ANGLES};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('components',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();